const res = await api.get('/mails', {});
// assume res is array of mail objects
if (!Array.isArray(res) || res.length===0) { return '메일이 없습니다.'; }
// find most recent by received_at if exists
let recent = res[0];
if (res[0].received_at) {
  recent = res.reduce((a,b)=> new Date(b.received_at) > new Date(a.received_at) ? b : a, res[0]);
}
return {id: recent.id, sender_email: recent.sender_email};

